{
  gkyl_ref_count_inc(&gpm->ref_count);
  return (struct gkyl_position_map *)gpm;
}

void gkyl_position_map_release(const struct gkyl_position_map *gpm)
{
  gkyl_ref_count_dec(&gpm->ref_count);
