      if (fabs(dB_dCell) > max_dB_dCell) {
        max_dB_dCell = fabs(dB_dCell);
      }
    }
    double improvement = max_dB_dCell_prior - max_dB_dCell;
    if (improvement > 1e-3) {
      expander_order++;
      max_dB_dCell_prior = max_dB_dCell;
    } else if (improvement < 0) {
      expander_order--;
