static void position_map_constB_z_numeric(double t, const double *xn, double *fout, void *ctx)
{
  struct gkyl_position_map *gpm = ctx;
  int num_boundaries = gpm->constB_ctx->N_theta_boundaries;
  double *theta_extrema = gpm->constB_ctx->theta_extrema;
  int num_extrema = gpm->constB_ctx->num_extrema;
  double theta_hi = gpm->constB_ctx->theta_max;
  double theta_lo = gpm->constB_ctx->theta_min;
  double theta_range = theta_hi - theta_lo;
  double theta_dxi = theta_range / num_boundaries;
  double theta = xn[0];
  double dB_cell = gpm->constB_ctx->dB_cell;
  double it = (theta - theta_lo) / theta_dxi;

  // Set strict floor and ceiling limits for theta
  // This is to prevent the root finding algorithm from going out of bounds
  // Not fout[0] = theta because of the finite differences and can lead to jumps
  if (it <= 0 || it >= num_boundaries) {
    fout[0] = (it <= 0) ? theta_lo : theta_hi;
    return;
  }

  // A constant field has no preferred redistribution. Also preserve the
  // identity exactly when the requested mapping strength is zero.
  double bscale = 0.0;
  for (int i = 0; i < num_extrema; ++i) {
    bscale = fmax(bscale, fabs(gpm->constB_ctx->bmag_extrema[i]));
  }
  if (gpm->constB_ctx->map_strength == 0.0 ||
      dB_cell * num_boundaries <= 64.0 * DBL_EPSILON * bscale) {
    fout[0] = theta;
    return;
  }

  // Determine which region theta is in
  // Regions start at 0 and count up to num_extrema-1
  // Initial guess is not accurate because the theta_extrema are not Theta_extrema
  // We use itteration to further refine this, but it's a good initial guess
  int region = 0;
  for (int i = 1; i <= num_extrema - 2; i++) {
    if (theta >= theta_extrema[i]) {
      region = i;
    } else {
      break;
    }
  }

  double dB_target, dB_global_lower, B_lower_region;
  double interval_lower, interval_upper, interval_lower_eval, interval_upper_eval;
  struct opt_Theta_ctx ridders_ctx = {.gpm = gpm, .bmag_ctx = gpm->bmag_ctx};
  dB_target = dB_cell * it;

  double Theta;
  bool outside_region = true; // Asuume that we identified the region incorrectly
  while (outside_region) {
    dB_global_lower = 0.0;
    for (int i = 0; i < region; i++) {
      dB_global_lower +=
        fabs(gpm->constB_ctx->bmag_extrema[i + 1] - gpm->constB_ctx->bmag_extrema[i]);
    }
    B_lower_region = gpm->constB_ctx->bmag_extrema[region];

    ridders_ctx.dB_target = dB_target;
    ridders_ctx.dB_global_lower = dB_global_lower;
    ridders_ctx.B_lower_region = B_lower_region;

    interval_lower = theta_extrema[region];
    interval_upper = theta_extrema[region + 1];
    interval_lower_eval = position_map_numeric_optimization_function(interval_lower, &ridders_ctx);
    interval_upper_eval = position_map_numeric_optimization_function(interval_upper, &ridders_ctx);

    if (interval_lower_eval * interval_upper_eval < 0) {
      // If the interval changes sign, then there is a zero in between. We can find the root and are in the correct region
      outside_region = false;
    } else if (fabs(interval_lower_eval) < 16.0 * DBL_EPSILON * bscale ||
               fabs(interval_upper_eval) < 16.0 * DBL_EPSILON * bscale) {
      // If either evaluation is very close to zero, we're at or very near the solution
      // Just use the corresponding endpoint
      Theta = fabs(interval_lower_eval) < fabs(interval_upper_eval) ? interval_lower :
                                                                      interval_upper;
      goto map_value;
    } else {
      // It means we are in the wrong region
      if (interval_lower_eval > 0.0 && interval_upper_eval > 0.0) {
        // If the bounds on the interval are both positive, we should move down a region to make it pass through zero
        region--;
        if (region < 0) {
          // If we can't move down any regions and leave the simulation domain, we are likely on the lower limit of the domain and should just return the input theta
          fout[0] = theta_lo;
          return;
        }
      } else if (interval_lower_eval < 0.0 && interval_upper_eval < 0.0) {
        // If the bounds on the interval are both negative, we should move up a region to make it pass through zero
        region++;
        if (region > num_extrema - 2) {
          // If we can't move up any regions and leave the simulation domain, we are likely on the upper limit of the domain and should just return the input theta
          fout[0] = theta_hi;
          return;
        }
      } else if (fabs(interval_lower_eval) < 1e-14) {
        // Lower evaluation is very close to zero
        Theta = interval_lower;
        goto map_value;
      } else if (fabs(interval_upper_eval) < 1e-14) {
        // Upper evaluation is very close to zero
        Theta = interval_upper;
        goto map_value;
      } else {
        fprintf(
          stderr,
          "Warning: Unexpected interval evaluation state in position_map_constB_z_numeric. Using "
          "theta directly.\n"
        );
        fout[0] = theta;
        return;
      }
    }
  }

  struct gkyl_qr_res res = gkyl_ridders(
    position_map_numeric_optimization_function, &ridders_ctx, interval_lower, interval_upper,
    interval_lower_eval, interval_upper_eval, 100, 1e-12
  );
  Theta = res.res;
map_value:
  fout[0] = Theta * gpm->constB_ctx->map_strength + theta * (1 - gpm->constB_ctx->map_strength);

  bool enable_limits_min_B = gpm->constB_ctx->enable_maximum_slope_limits_at_min_B;
  bool enable_limits_max_B = gpm->constB_ctx->enable_maximum_slope_limits_at_max_B;

  if (enable_limits_min_B || enable_limits_max_B) {
    // An extremum generally moves under the constant-dB map. Anchor the
    // limiting lines at its computational preimage, not its physical
    // coordinate, or the map jumps when root finding changes regions.
    double total_change = dB_cell * num_boundaries;
    double theta_left = theta_lo + theta_range * dB_global_lower / total_change;
    double region_change = fabs(gpm->constB_ctx->bmag_extrema[region + 1] - B_lower_region);
    double theta_right = theta_lo + theta_range * (dB_global_lower + region_change) / total_change;
    double strength = gpm->constB_ctx->map_strength;
    double Theta_left = strength * interval_lower + (1.0 - strength) * theta_left;
    double Theta_right = strength * interval_upper + (1.0 - strength) * theta_right;
    double theta_middle = 0.5 * (theta_left + theta_right);

    bool left_is_maximum = gpm->constB_ctx->min_or_max[region];
    bool right_is_maximum = gpm->constB_ctx->min_or_max[region + 1];

    if (theta > theta_middle && left_is_maximum) {
      enable_limits_max_B = false;
    }
    if (theta < theta_middle && right_is_maximum) {
      enable_limits_max_B = false;
    }

    double max_slope_min_B = gpm->constB_ctx->maximum_slope_at_min_B;
    double max_slope_max_B = gpm->constB_ctx->maximum_slope_at_max_B;

    double right_straight_line_value, left_straight_line_value;
    if (left_is_maximum) {
      left_straight_line_value = Theta_left + max_slope_max_B * (theta - theta_left);
    } else {
      left_straight_line_value = Theta_left + max_slope_min_B * (theta - theta_left);
    }

    if (right_is_maximum) {
      right_straight_line_value = Theta_right + max_slope_max_B * (theta - theta_right);
    } else {
      right_straight_line_value = Theta_right + max_slope_min_B * (theta - theta_right);
    }

    if (fout[0] < right_straight_line_value && ((right_is_maximum && enable_limits_max_B) ||
                                                ((!right_is_maximum) && enable_limits_min_B))) {
      fout[0] = right_straight_line_value;
    }

    if (fout[0] > left_straight_line_value &&
        ((left_is_maximum && enable_limits_max_B) || ((!left_is_maximum) && enable_limits_min_B))) {
      fout[0] = left_straight_line_value;
    }
  }
}

// Context for Gaussian-weighted integration
struct gaussian_weight_ctx {
  struct gkyl_position_map *gpm;
  double theta_c; // Center point for Gaussian
  double wd2; // Half-width of averaging window
  double sigma; // Standard deviation for Gaussian weight
};

double position_map_constB_z_numeric_dbl_exp_wrapper(double z, void *ctx)
{
  struct gaussian_weight_ctx *gw_ctx = ctx;
  double fout[3];
  position_map_constB_z_numeric(0.0, &z, fout, gw_ctx->gpm);

  // Apply Gaussian weight: exp(-(z-theta_c)^2 / (2*sigma^2))
  double dz = z - gw_ctx->theta_c;
  double weight = exp(-dz * dz / (2.0 * gw_ctx->sigma * gw_ctx->sigma));

  return fout[0] * weight;
}

double gaussian_norm_wrapper(double z, void *ctx)
{
  struct gaussian_weight_ctx *gw_ctx = ctx;

  // Return just the Gaussian weight for normalization
  double dz = z - gw_ctx->theta_c;
  double weight = exp(-dz * dz / (2.0 * gw_ctx->sigma * gw_ctx->sigma));

  return weight;
}

/**
 * Maps the uniform computational coordinate to a non-uniform coordinate
 * according to the numeric constant B mapping.
 * 
 * @param t Time
 * @param xn Uniform coordinate
 * @param fout Non-uniform coordinate
 * @param ctx The context for the position map
 */
static void
position_map_constB_z_numeric_moving_average(double t, const double *xn, double *fout, void *ctx)
{
  struct gkyl_position_map *gpm = ctx;
  if (gpm->constB_ctx->gaussian_std == 0.0) {
    position_map_constB_z_numeric(t, xn, fout, ctx);
    return;
  }

  const double theta_c = xn[0];
  const double sigma = gpm->constB_ctx->gaussian_std;
  const double max_width = gpm->constB_ctx->gaussian_max_integration_width;
  const double tmin = gpm->constB_ctx->theta_min;
  const double tmax = gpm->constB_ctx->theta_max;

static void asymmetric_bmag(double t, const double *xn, double *out, void *ctx)
{
  bool flat = *(bool *)ctx;
  out[0] = flat ? 2.0 : xn[0] < 0.25 ? 2.0 - xn[0] : 1.75 + 2.0 * (xn[0] - 0.25);
}

static void test_numeric_degenerate_and_strength(void)
{
  for (int flat = 0; flat < 2; ++flat) {
    struct gkyl_rect_grid grid, grid3;
    gkyl_rect_grid_init(&grid, 1, (double[]){-1}, (double[]){1}, (int[]){16});
    gkyl_rect_grid_init(&grid3, 3, (double[]){-2, -1, -1}, (double[]){-1, 1, 1}, (int[]){1, 1, 16});
    struct gkyl_range local, ext, global3, ext3;
    gkyl_create_grid_ranges(&grid, (int[]){1}, &ext, &local);
    gkyl_create_grid_ranges(&grid3, (int[]){1, 1, 1}, &ext3, &global3);
    struct gkyl_basis basis;
    gkyl_cart_modal_serendip(&basis, 1, 1);
    struct gkyl_position_map *pmap = gkyl_position_map_new(
      (struct gkyl_position_map_inp){.id = GKYL_PMAP_CONSTANT_DB_NUMERIC, .map_strength = 1.0},
      grid, local, ext, local, ext, basis
    );
    struct gkyl_array *bmag = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, ext.volume);
    bool uniform = flat;
    struct gkyl_proj_on_basis *proj =
      gkyl_proj_on_basis_new(&grid, &basis, 2, 1, asymmetric_bmag, &uniform);
    gkyl_proj_on_basis_advance(proj, 0.0, &local, bmag);
    gkyl_proj_on_basis_release(proj);
    gkyl_position_map_optimize(pmap, grid3, global3);
    gkyl_position_map_set_bmag(pmap, NULL, bmag);
    gkyl_position_map_optimize(pmap, grid3, global3);
    TEST_CHECK(gkyl_compare(pmap->constB_ctx->psi, -1.5, 1e-14));
    for (int strength = 0; strength < 3; ++strength) {
      pmap->constB_ctx->map_strength = 0.5 * strength;
      for (int point = 0; point <= 32; ++point) {
        // Include the exact computational location of the asymmetric minimum.
        double x = point == 16 ? -1.0 + 2.0 * 1.25 / 2.75 : -1.0 + point / 16.0;
        double full, actual;
        pmap->constB_ctx->map_strength = 1.0;
        pmap->maps[2](0, &x, &full, pmap->ctxs[2]);
        pmap->constB_ctx->map_strength = 0.5 * strength;
        pmap->maps[2](0, &x, &actual, pmap->ctxs[2]);
        double expected = uniform ? x : (1.0 - 0.5 * strength) * x + 0.5 * strength * full;
        TEST_CHECK(gkyl_compare(actual, expected, 2e-12));
        TEST_MSG(
          "flat %d strength %g x %g actual %g expected %g", flat, 0.5 * strength, x, actual,
          expected
        );
      }
    }
    if (!uniform) {
      pmap->constB_ctx->enable_maximum_slope_limits_at_min_B = true;
      pmap->constB_ctx->enable_maximum_slope_limits_at_max_B = true;
      pmap->constB_ctx->maximum_slope_at_min_B = 2.0;
      pmap->constB_ctx->maximum_slope_at_max_B = 2.0;
      double x_min = -1.0 + 2.0 * 1.25 / 2.75;
      for (int strength = 1; strength <= 2; ++strength) {
        pmap->constB_ctx->map_strength = strength * 0.5;
        double left = x_min - 1e-8, right = x_min + 1e-8, mapped_left, mapped_right;
        pmap->maps[2](0, &left, &mapped_left, pmap->ctxs[2]);
        pmap->maps[2](0, &right, &mapped_right, pmap->ctxs[2]);
        TEST_CHECK(mapped_right >= mapped_left);
        TEST_CHECK(mapped_right - mapped_left < 4e-8);
        double previous = -1.0;
        for (int i = 1; i <= 256; ++i) {
          double x = -1.0 + i / 128.0, mapped;
          pmap->maps[2](0, &x, &mapped, pmap->ctxs[2]);
          TEST_CHECK(mapped > previous);
          TEST_CHECK(mapped - previous <= 2.0 / 128.0 + 1e-12);
          previous = mapped;
        }
      }
    }
    // Replacing B must release the previous optimization storage.
    gkyl_position_map_set_bmag(pmap, NULL, bmag);
    gkyl_position_map_optimize(pmap, grid3, global3);
    gkyl_array_release(bmag);
    gkyl_position_map_release(pmap);
  }
}

